  "vocab.deleteOne.confirm": ["Delete word", "Eliminar palabra", "Supprimer le mot", "Wort löschen", "Elimina parola", "Excluir palavra", "単語を削除", "删除单词", "단어 삭제"],
  "vocab.deleteMany.confirm": ["Delete {count} words", "Eliminar {count} palabras", "Supprimer {count} mots", "{count} Wörter löschen", "Elimina {count} parole", "Excluir {count} palavras", "{count}個の単語を削除", "删除 {count} 个单词", "단어 {count}개 삭제"],
  "vocab.deleteBody": ["They will be removed from your list. This can't be undone.", "Se quitarán de tu lista. Esta acción no se puede deshacer.", "Ils seront retirés de ta liste. Cette action est irréversible.", "Sie werden aus deiner Liste entfernt. Das kann nicht rückgängig gemacht werden.", "Verranno rimosse dal tuo elenco. L'operazione non si può annullare.", "Elas serão removidas da sua lista. Isso não pode ser desfeito.", "リストから削除されます。この操作は元に戻せません。", "它们将从你的列表中移除，且无法恢复。", "목록에서 삭제돼요. 되돌릴 수 없어요."],
  "vocab.deleted.one": ["Deleted 1 word", "Se eliminó 1 palabra", "1 mot supprimé", "1 Wort gelöscht", "1 parola eliminata", "1 palavra excluída", "1個の単語を削除しました", "已删除 1 个单词", "단어 1개를 삭제했어요"],
  "vocab.deleted.other": ["Deleted {count} words", "Se eliminaron {count} palabras", "{count} mots supprimés", "{count} Wörter gelöscht", "{count} parole eliminate", "{count} palavras excluídas", "{count}個の単語を削除しました", "已删除 {count} 个单词", "단어 {count}개를 삭제했어요"],
  "vocab.added": ["Added “{word}”", "Se añadió «{word}»", "« {word} » ajouté", "„{word}“ hinzugefügt", "Aggiunta «{word}»", "“{word}” adicionada", "「{word}」を追加しました", "已添加“{word}”", "“{word}”을(를) 추가했어요"],
  "vocab.upload.result": ["Added {added}, duplicates {duplicates}, invalid {invalid}.", "Añadidas {added}, duplicadas {duplicates}, no válidas {invalid}.", "Ajoutés : {added}, doublons : {duplicates}, invalides : {invalid}.", "Hinzugefügt: {added}, Duplikate: {duplicates}, ungültig: {invalid}.", "Aggiunte {added}, duplicate {duplicates}, non valide {invalid}.", "Adicionadas {added}, duplicadas {duplicates}, inválidas {invalid}.", "追加 {added}件、重複 {duplicates}件、無効 {invalid}件。", "已添加 {added} 个，重复 {duplicates} 个，无效 {invalid} 个。", "추가 {added}개, 중복 {duplicates}개, 잘못된 항목 {invalid}개."],
  "vocab.upload.row": ["Row {row}: {reason}", "Fila {row}: {reason}", "Ligne {row} : {reason}", "Zeile {row}: {reason}", "Riga {row}: {reason}", "Linha {row}: {reason}", "{row}行目：{reason}", "第 {row} 行：{reason}", "{row}행: {reason}"],
  "vocab.loadingWords": ["Loading words", "Cargando palabras", "Chargement des mots", "Wörter werden geladen", "Caricamento delle parole", "Carregando palavras", "単語を読み込み中", "正在加载单词", "단어를 불러오는 중"],
  "vocab.noMatch.title": ["No words match your search", "Ninguna palabra coincide con tu búsqueda", "Aucun mot ne correspond à ta recherche", "Keine Wörter passen zu deiner Suche", "Nessuna parola corrisponde alla ricerca", "Nenhuma palavra corresponde à busca", "検索に一致する単語がありません", "没有符合搜索的单词", "검색과 일치하는 단어가 없어요"],
  "vocab.noMatch.body": ["Try a different spelling, or clear the search box.", "Prueba otra ortografía o borra el cuadro de búsqueda.", "Essaie une autre orthographe ou vide la zone de recherche.", "Versuche eine andere Schreibweise oder leere das Suchfeld.", "Prova un'altra grafia o svuota la casella di ricerca.", "Tente outra grafia ou limpe a caixa de busca.", "別のつづりを試すか、検索ボックスを空にしてください。", "试试其他拼写，或清空搜索框。", "철자를 바꿔 보거나 검색창을 비워 보세요."],
  "vocab.empty.title": ["No words yet", "Aún no hay palabras", "Pas encore de mots", "Noch keine Wörter", "Ancora nessuna parola", "Ainda sem palavras", "まだ単語がありません", "还没有单词", "아직 단어가 없어요"],
  "vocab.empty.body": ["Add a word above, or upload a CSV with a “word” column (and optionally “meaning”).", "Añade una palabra arriba o sube un CSV con una columna «word» (y, si quieres, «meaning»).", "Ajoute un mot ci-dessus ou importe un CSV avec une colonne « word » (et éventuellement « meaning »).", "Füge oben ein Wort hinzu oder lade eine CSV-Datei mit einer Spalte „word“ (und optional „meaning“) hoch.", "Aggiungi una parola qui sopra o carica un CSV con una colonna «word» (e facoltativamente «meaning»).", "Adicione uma palavra acima ou envie um CSV com uma coluna “word” (e, se quiser, “meaning”).", "上で単語を追加するか、「word」列（任意で「meaning」列）のあるCSVをアップロードしてください。", "在上方添加单词，或上传带有 “word” 列（可选 “meaning” 列）的 CSV。", "위에서 단어를 추가하거나 “word” 열(선택적으로 “meaning” 열)이 있는 CSV를 업로드하세요."],
  "vocab.empty.action": ["Add your first word", "Añade tu primera palabra", "Ajoute ton premier mot", "Erstes Wort hinzufügen", "Aggiungi la tua prima parola", "Adicione sua primeira palavra", "最初の単語を追加", "添加第一个单词", "첫 단어 추가하기"],
  "vocab.selectAll": ["Select all on this page", "Seleccionar todo en esta página", "Tout sélectionner sur cette page", "Alle auf dieser Seite auswählen", "Seleziona tutto in questa pagina", "Selecionar tudo nesta página", "このページをすべて選択", "选择本页全部", "이 페이지 전체 선택"],
  "vocab.select": ["Select {word}", "Seleccionar {word}", "Sélectionner {word}", "{word} auswählen", "Seleziona {word}", "Selecionar {word}", "{word}を選択", "选择 {word}", "{word} 선택"],
  "vocab.colWord": ["Word", "Palabra", "Mot", "Wort", "Parola", "Palavra", "単語", "单词", "단어"],
