  "tool.failed": ["{name} didn't work", "{name} no funcionó", "{name} n'a pas fonctionné", "{name} hat nicht funktioniert", "{name} non ha funzionato", "{name} não funcionou", "{name}は失敗しました", "{name} 未能完成", "{name}이(가) 작동하지 않았어요"],
  "tool.sent": ["Sent", "Enviado", "Envoyé", "Gesendet", "Inviato", "Enviado", "送信内容", "发送内容", "보낸 내용"],
